CREATE TABLE IF NOT EXISTS public.cashier_closings (closing_id TEXT PRIMARY KEY,business_id TEXT NOT NULL,outlet_id TEXT NOT NULL,outlet_name TEXT NOT NULL,cashier_user_id TEXT NOT NULL,cashier_name TEXT NOT NULL,shift_started_at BIGINT NOT NULL,closed_at BIGINT NOT NULL,date_key TEXT NOT NULL,items JSONB NOT NULL DEFAULT '[]'::jsonb,total_stock_in NUMERIC NOT NULL DEFAULT 0,total_stock_sold NUMERIC NOT NULL DEFAULT 0,total_stock_damaged NUMERIC NOT NULL DEFAULT 0,total_stock_remaining NUMERIC NOT NULL DEFAULT 0,total_stock_returned NUMERIC NOT NULL DEFAULT 0,gross_income NUMERIC NOT NULL DEFAULT 0,total_expense NUMERIC NOT NULL DEFAULT 0,net_income NUMERIC NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'READY_FOR_CLOCK_OUT',CONSTRAINT cashier_closings_cashier_user_id_shift_started_at_key UNIQUE(cashier_user_id,shift_started_at));
CREATE INDEX IF NOT EXISTS idx_cashier_closings_business_date ON public.cashier_closings(business_id,date_key DESC);
CREATE INDEX IF NOT EXISTS idx_cashier_closings_cashier_date ON public.cashier_closings(cashier_user_id,date_key DESC);
ALTER TABLE public.cashier_closings ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN CREATE POLICY "Allow public all on cashier_closings" ON public.cashier_closings FOR ALL USING(true) WITH CHECK(true); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
